package cn.dreamingfish.updater.player.launcher.web;
import cn.dreamingfish.launcher.downloads.*;
import cn.dreamingfish.launcher.mods.*;
import cn.dreamingfish.launcher.storage.LauncherJson;
import java.io.*;
import java.util.*;
public final class ModRoutes implements LauncherRoutes {
 private final ModService service;private final ModLibrary library;private final TaskManager tasks;
 public ModRoutes(ModService service,ModLibrary library,TaskManager tasks){this.service=service;this.library=library;this.tasks=tasks;}
 @Override public Optional<ApiResponse> handle(ApiRequest r)throws IOException{
  if(!r.path().startsWith("/mods/"))return Optional.empty();var token=new CancellationToken();
  try{
   Object result;
   switch(r.path()){
    case "/mods/sources"->{r.requireMethod("GET");r.onlyQuery();result=Map.of("sources",service.statuses(token).stream().map(ModRoutes::status).toList());}
    case "/mods/categories"->{r.requireMethod("GET");r.onlyQuery("source");result=Map.of("categories",service.categories(source(r),token));}
    case "/mods/search"->{r.requireMethod("GET");r.onlyQuery("source","q","gameVersion","loader","sort","offset","limit","category");var query=new ModQuery(r.query().getOrDefault("q",""),r.query().getOrDefault("gameVersion",""),r.query().getOrDefault("loader",""),ModQuery.Sort.valueOf(r.query().getOrDefault("sort","RELEVANCE").toUpperCase(Locale.ROOT)),offset(r),limit(r),r.query().getOrDefault("category",""));var page=service.search(source(r),query,token);result=page(page.items().stream().map(ModRoutes::project).toList(),page.offset(),page.limit(),page.total(),page.accessibleTotal(),page.platformLimited());}
    case "/mods/project"->{r.requireMethod("GET");r.onlyQuery("source","projectId");result=Map.of("project",project(service.project(source(r),projectId(r),token)));}
    case "/mods/files"->{r.requireMethod("GET");r.onlyQuery("source","projectId","gameVersion","loader","offset","limit");var query=new ModFileQuery(r.query().getOrDefault("gameVersion",""),r.query().getOrDefault("loader",""),offset(r),limit(r));var page=service.files(source(r),projectId(r),query,token);result=page(page.items().stream().map(ModRoutes::file).toList(),page.offset(),page.limit(),page.total(),page.accessibleTotal(),page.platformLimited());}
    case "/mods/downloads"->{r.requireMethod("POST");r.onlyQuery();r.onlyFields(Set.of("ref","gameVersion","loader"));var n=r.body().path("ref");var fields=new HashSet<String>();n.fieldNames().forEachRemaining(fields::add);if(!n.isObject()||!fields.equals(Set.of("source","projectId","versionId","fileKey")))throw ApiRequest.invalid("文件引用字段无效");var ref=new ModFileRef(ModSource.valueOf(LauncherJson.text(n,"source",16)),LauncherJson.text(n,"projectId",128),LauncherJson.text(n,"versionId",128),LauncherJson.text(n,"fileKey",64));var task=tasks.submit(service.prepareDownload(ref,r.text("gameVersion",128),r.text("loader",32),token));return Optional.of(new ApiResponse(202,Map.of("task",TaskRoutes.view(task))));}
    case "/mods/library"->{r.requireMethod("GET");r.onlyQuery();var listing=library.listing();var entries=new ArrayList<Map<String,Object>>();for(var entry:listing.entries())entries.add(entry(entry,library.filePath(entry).toString()));result=Map.of("entries",entries,"problems",listing.problems().stream().map(p->Map.of("recordId",p.entryId(),"message",p.reason())).toList());}
    default->{String prefix="/mods/library/",suffix="/verify";if(!r.path().startsWith(prefix)||!r.path().endsWith(suffix))throw new LauncherApiException(404,"NOT_FOUND","模组操作不存在");r.requireMethod("POST");r.onlyQuery();r.onlyFields(Set.of());String id=r.path().substring(prefix.length(),r.path().length()-suffix.length());TaskRequest.uuid(id);if(library.listing().entries().stream().noneMatch(e->e.id().toString().equals(id)))throw new LauncherApiException(404,"NOT_FOUND","模组库记录不存在或损坏");var task=tasks.submit(new TaskRequest(TaskKind.MOD_VERIFY,Map.of("entryId",id)));return Optional.of(new ApiResponse(202,Map.of("task",TaskRoutes.view(task))));}
   }
   return Optional.of(new ApiResponse(200,result));
  }catch(TaskFailure failure){int status=switch(failure.code()){case "SOURCE_UNCONFIGURED","QUEUE_FULL","BUSY"->503;case "AUTH_REQUIRED"->412;case "NETWORK_ERROR"->502;case "UNKNOWN_LOADER","UNKNOWN_CATEGORY"->400;default->409;};throw new LauncherApiException(status,failure.code(),failure.getMessage());}
  catch(RemoteHttpException failure){if(failure.status()==429)return Optional.of(new ApiResponse(429,Map.of("error",Map.of("code","RATE_LIMITED","message",failure.getMessage(),"retryAfterSeconds",failure.retryAfterSeconds()==null?60:failure.retryAfterSeconds()))));throw new LauncherApiException(502,"SOURCE_UNAVAILABLE","官方模组来源暂不可用");}
  catch(IllegalArgumentException invalid){throw ApiRequest.invalid("模组参数、引用或筛选条件无效");}
 }
 private static int offset(ApiRequest r){return CatalogRoutes.number(r.query(),"offset",0,0,Integer.MAX_VALUE);}private static int limit(ApiRequest r){return CatalogRoutes.number(r.query(),"limit",20,1,50);}
 private static ModSource source(ApiRequest r){return ModSource.valueOf(r.query().getOrDefault("source","MODRINTH"));}
 private static String projectId(ApiRequest r){String id=r.query().get("projectId");if(id==null||!id.matches("[A-Za-z0-9_-]{1,128}"))throw ApiRequest.invalid("项目 ID 无效");return id;}
 private static Map<String,Object> page(List<?> items,int offset,int limit,long total,long accessible,boolean limited){return Map.of("items",items,"offset",offset,"limit",limit,"total",total,"accessibleTotal",accessible,"platformLimited",limited);}
 private static Map<String,Object> status(SourceStatus s){var m=new LinkedHashMap<String,Object>();m.put("source",s.source().name());m.put("state",s.state());m.put("reason",s.reason());m.put("loaders",s.loaders());m.put("warning",s.warning());return m;}
 private static Map<String,Object> project(ModProject p){var m=new LinkedHashMap<String,Object>();m.put("source",p.source().name());m.put("projectId",p.projectId());m.put("title",p.title());m.put("author",p.author());m.put("summary",p.summary());m.put("downloads",p.downloads());m.put("presentation",p.presentation());return m;}
 private static Map<String,Object> dependency(ModDependency d){var m=new LinkedHashMap<String,Object>();m.put("kind",d.kind().name());m.put("projectId",d.projectId());m.put("versionId",d.versionId());m.put("fileName",d.fileName());return m;}
 private static Map<String,Object> hash(FileDigest hash){return hash==null?null:Map.of("algorithm",hash.algorithm().name(),"hex",hash.hex());}
 private static Map<String,Object> file(ModFile f){var m=new LinkedHashMap<String,Object>();m.put("ref",Map.of("source",f.ref().source().name(),"projectId",f.ref().projectId(),"versionId",f.ref().versionId(),"fileKey",f.ref().fileKey()));m.put("displayName",f.displayName());m.put("fileName",f.fileName());m.put("gameVersions",f.gameVersions());m.put("loaders",f.loaders());m.put("releaseChannel",f.releaseChannel());m.put("publishedAt",f.publishedAt()==null?null:f.publishedAt().toString());m.put("size",f.size());m.put("sourceDigest",hash(f.sourceDigest()));m.put("dependencies",f.dependencies().stream().map(ModRoutes::dependency).toList());m.put("downloadable",f.downloadable());m.put("blockedReason",f.blockedReason());return m;}
 private static Map<String,Object> entry(ModLibraryEntry e,String path){var m=new LinkedHashMap<String,Object>();m.put("id",e.id().toString());m.put("taskId",e.taskId().toString());m.put("source",e.source().name());m.put("projectId",e.projectId());m.put("versionId",e.versionId());m.put("fileKey",e.fileKey());m.put("title",e.title());m.put("fileName",e.fileName());m.put("gameVersions",e.gameVersions());m.put("loaders",e.loaders());m.put("sourceDigest",hash(e.sourceDigest()));m.put("size",e.size());m.put("sha256",e.sha256());m.put("createdAt",e.createdAt().toString());m.put("dependencies",e.dependencies().stream().map(ModRoutes::dependency).toList());m.put("filePath",path);return m;}
}
